with with_prev as (select *, lag(reading_ts) over (partition by device_code order by reading_ts, id) as prev_reading_ts from device_readings), flagged as (select *, case when prev_reading_ts is null or reading_ts > prev_reading_ts + interval '30' minute then 1 else 0 end as is_new_session from with_prev) select id, device_code, reading_ts, temp_c, humidity, pressure, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_no from flagged
